import java.util.*;

class Solution {
    private final Map<String, Integer> memo = new HashMap<>();
    private int base;

    public int leastOpsExpressTarget(int x, int target) {
        base = x;
        return dfs(target, 0) - 1;
    }

    private int dfs(int target, int pos) {
        if (target == 0) {
            return 0;
        }
        if (target == 1) {
            return pos == 0 ? 2 : pos;
        }
        String key = target + ":" + pos;
        Integer cached = memo.get(key);
        if (cached != null) {
            return cached;
        }

        int digit = target % base;
        int rest = target / base;
        int costPerPower = pos == 0 ? 2 : pos;
        int useDigit = digit * costPerPower + dfs(rest, pos + 1);
        int roundUp = Integer.MAX_VALUE / 4;
        if (digit != 0) {
            roundUp = (base - digit) * costPerPower + dfs(rest + 1, pos + 1);
        }
        int best = Math.min(useDigit, roundUp);
        memo.put(key, best);
        return best;
    }
}

class Solution {
    public int leastOpsExpressTarget(int x, int target) {
        int pos = 0;
        int noCarry = 0;
        int carry = 0;
        while (target > 0) {
            int digit = target % x;
            target /= x;
            int costPerPower = pos == 0 ? 2 : pos;
            if (pos == 0) {
                noCarry = digit * costPerPower;
                carry = (x - digit) * costPerPower;
            } else {
                int nextNoCarry = Math.min(
                        noCarry + digit * costPerPower,
                        carry + (digit + 1) * costPerPower);
                int nextCarry = Math.min(
                        noCarry + (x - digit) * costPerPower,
                        carry + (x - digit - 1) * costPerPower);
                noCarry = nextNoCarry;
                carry = nextCarry;
            }
            pos++;
        }
        return Math.min(noCarry, carry + pos) - 1;
    }
}

import java.util.*;

class Solution {
    private int x;
    private Map<Integer, Integer> memo;

    public int leastOpsExpressTarget(int x, int target) {
        this.x = x;
        this.memo = new HashMap<>();
        return solve(target);
    }

    private int solve(int target) {
        if (target == 0) {
            return 0;
        }
        if (target < x) {
            return Math.min(2 * target - 1, 2 * (x - target));
        }
        Integer cached = memo.get(target);
        if (cached != null) {
            return cached;
        }

        long power = x;
        int exponent = 1;
        while (power * x <= target) {
            power *= x;
            exponent++;
        }
        if (power == target) {
            return exponent - 1;
        }

        int best = exponent + solve((int) (target - power));
        long nextPower = power * x;
        if (nextPower - target < target) {
            best = Math.min(best, exponent + 1 + solve((int) (nextPower - target)));
        }
        memo.put(target, best);
        return best;
    }
}

import java.util.*;

class Solution {
    private int x;
    private List<Integer> digits;
    private int[][] memo;

    public int leastOpsExpressTarget(int x, int target) {
        this.x = x;
        digits = new ArrayList<>();
        while (target > 0) {
            digits.add(target % x);
            target /= x;
        }
        memo = new int[digits.size() + 1][2];
        for (int[] row : memo) {
            Arrays.fill(row, -1);
        }
        return dp(0, 0) - 1;
    }

    private int dp(int pos, int carry) {
        if (pos == digits.size()) {
            return carry == 0 ? 0 : costOfPower(pos);
        }
        if (memo[pos][carry] != -1) {
            return memo[pos][carry];
        }
        int digit = digits.get(pos) + carry;
        int costPerPower = costOfPower(pos);
        int clearCarry = digit * costPerPower + dp(pos + 1, 0);
        int keepCarry = (x - digit) * costPerPower + dp(pos + 1, 1);
        memo[pos][carry] = Math.min(clearCarry, keepCarry);
        return memo[pos][carry];
    }

    private int costOfPower(int pos) {
        return pos == 0 ? 2 : pos;
    }
}

import java.util.*;

class Solution {
    public int leastOpsExpressTarget(int x, int target) {
        List<Integer> digits = new ArrayList<>();
        while (target > 0) {
            digits.add(target % x);
            target /= x;
        }
        int n = digits.size();
        int[][] dist = new int[n + 1][2];
        for (int[] row : dist) {
            Arrays.fill(row, Integer.MAX_VALUE / 4);
        }
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        dist[0][0] = 0;
        pq.offer(new int[] {0, 0, 0});

        int best = Integer.MAX_VALUE;
        while (!pq.isEmpty()) {
            int[] state = pq.poll();
            int cost = state[0];
            int pos = state[1];
            int carry = state[2];
            if (cost != dist[pos][carry]) {
                continue;
            }
            if (pos == n) {
                int total = cost + (carry == 0 ? 0 : costOfPower(pos));
                best = Math.min(best, total);
                continue;
            }

            int digit = digits.get(pos) + carry;
            int costPerPower = costOfPower(pos);
            relax(dist, pq, pos + 1, 0, cost + digit * costPerPower);
            relax(dist, pq, pos + 1, 1, cost + (x - digit) * costPerPower);
        }
        return best - 1;
    }

    private void relax(int[][] dist, PriorityQueue<int[]> pq, int pos, int carry, int cost) {
        if (cost < dist[pos][carry]) {
            dist[pos][carry] = cost;
            pq.offer(new int[] {cost, pos, carry});
        }
    }

    private int costOfPower(int pos) {
        return pos == 0 ? 2 : pos;
    }
}
